create or replace function public.resolve_gateway_credential(p_credential_id uuid, p_organization_id uuid) returns jsonb language plpgsql security definer set search_path='public','vault','pg_catalog' as $function$ declare v_gateway public.user_gateway_credentials%rowtype; v_secret text; v_json jsonb; v_api_key text; begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'forbidden' using errcode='42501'; end if; if p_organization_id is null then raise exception 'organization_context_required' using errcode='22023'; end if; select * into v_gateway from public.user_gateway_credentials where id=p_credential_id and is_active=true limit 1; if not found then raise exception 'gateway_credential_not_found' using errcode='P0002'; end if; if v_gateway.organization_id is distinct from p_organization_id then raise exception 'gateway_credential_organization_mismatch' using errcode='42501', detail='The requested credential does not belong to the supplied organization'; end if; if v_gateway.secret_ref is not null then select decrypted_secret into v_secret from vault.decrypted_secrets where id=v_gateway.secret_ref::uuid limit 1; elsif v_gateway.api_key_encrypted is not null then v_secret := extensions.pgp_sym_decrypt(decode(v_gateway.api_key_encrypted,'base64'),public.althea_gateway_encryption_key()); end if; if coalesce(v_secret,'')='' then raise exception 'gateway_credential_secret_unavailable'; end if; begin v_json := v_secret::jsonb; exception when others then v_json := null; end; if jsonb_typeof(v_json)='object' then v_api_key := coalesce(nullif(v_json->>'api_key',''),nullif(v_json->>'access_token',''),nullif(v_json->>'secret_key','')); return jsonb_build_object('id',v_gateway.id,'gateway_name',v_gateway.gateway_name,'api_key',v_api_key,'credentials',v_json,'metadata',coalesce(v_gateway.metadata,'{}'::jsonb),'priority_order',v_gateway.priority_order); end if; return jsonb_build_object('id',v_gateway.id,'gateway_name',v_gateway.gateway_name,'api_key',v_secret,'metadata',coalesce(v_gateway.metadata,'{}'::jsonb),'priority_order',v_gateway.priority_order); end $function$; create or replace function public.resolve_gateway_credential(p_credential_id uuid) returns jsonb language plpgsql security definer set search_path='public','vault','pg_catalog' as $function$ begin raise exception 'organization_context_required' using errcode='42501', detail='resolve_gateway_credential requires organization_id'; end $function$; create or replace function public.resolve_gateway_credential_for_gateway(p_gateway_id text) returns jsonb language plpgsql security definer set search_path='public','vault','pg_catalog' as $function$ declare g public.gateways%rowtype; base_bundle jsonb; registry_config jsonb; webhook_config jsonb; merged_credentials jsonb; begin if coalesce(auth.role(),'') <> 'service_role' then raise exception 'forbidden'; end if; select * into g from public.gateways where id=p_gateway_id and credential_id is not null limit 1; if not found then raise exception 'gateway_credential_not_bound'; end if; select public.resolve_gateway_credential(g.credential_id,g.organization_id) into base_bundle; if jsonb_typeof(base_bundle)<>'object' then raise exception 'gateway_credential_bundle_invalid'; end if; select coalesce(r.execution_config,'{}'::jsonb),coalesce(r.webhook_config,'{}'::jsonb) into registry_config,webhook_config from public.gateway_provider_registry r where r.provider_key=lower(trim(g.provider)) and r.is_active=true limit 1; if registry_config is null then raise exception 'provider_not_registered'; end if; merged_credentials:=registry_config||coalesce(base_bundle->'credentials','{}'::jsonb); return base_bundle||jsonb_build_object('gateway_id',g.id,'provider',g.provider,'environment',g.environment,'credentials',merged_credentials,'provider_config',registry_config,'webhook_config',webhook_config); end; $function$; create or replace function public.resolve_gateway_credential_bundle(p_gateway_id text) returns jsonb language plpgsql security definer set search_path='public','vault','pg_catalog' as $function$ declare g public.gateways%rowtype; c public.user_gateway_credentials%rowtype; r public.gateway_provider_registry%rowtype; secret text; credential_json jsonb; merged jsonb; begin if coalesce(auth.role(),'')<>'service_role' then raise exception 'forbidden'; end if; select * into g from public.gateways where id=p_gateway_id limit 1; if not found or g.credential_id is null then raise exception 'gateway_credential_not_bound'; end if; select * into c from public.user_gateway_credentials where id=g.credential_id and is_active=true limit 1; if not found then raise exception 'gateway_credential_not_found'; end if; if c.organization_id is distinct from g.organization_id then raise exception 'gateway_credential_organization_mismatch' using errcode='42501', detail='Gateway and credential belong to different organizations'; end if; if c.secret_ref is null then raise exception 'gateway_credential_not_found'; end if; select * into r from public.gateway_provider_registry where provider_key=lower(trim(g.provider)) and is_active=true limit 1; if not found then raise exception 'provider_not_registered'; end if; select decrypted_secret into secret from vault.decrypted_secrets where id=c.secret_ref::uuid limit 1; if coalesce(secret,'')='' then raise exception 'gateway_credential_secret_unavailable'; end if; begin credential_json:=secret::jsonb; exception when others then raise exception 'gateway_credential_bundle_invalid'; end; if jsonb_typeof(credential_json)<>'object' then raise exception 'gateway_credential_bundle_invalid'; end if; merged:=coalesce(r.execution_config,'{}'::jsonb)||credential_json; return jsonb_build_object('id',c.id,'gateway_id',g.id,'provider',g.provider,'environment',g.environment,'credentials',merged,'provider_config',coalesce(r.execution_config,'{}'::jsonb),'webhook_config',coalesce(r.webhook_config,'{}'::jsonb),'metadata',coalesce(c.metadata,'{}'::jsonb),'priority_order',c.priority_order); end $function$;